import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  if (!token) return res.status(401).json({ error: 'Missing tenant' });
  // In production this would verify JWT signature
  req.tenantId = token;
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/reports', extractTenant, async (req, res) => {
  try {
    const { status, date_from, date_to, sort_by, order } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, title, status, created_at, author 
                 FROM reports WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    if (date_from) {
      query += ` AND created_at >= $${paramIdx}`;
      params.push(date_from);
      paramIdx++;
    }

    if (date_to) {
      query += ` AND created_at <= $${paramIdx}`;
      params.push(date_to);
      paramIdx++;
    }

    // Dynamic ORDER BY - validated against allowlist
    const allowedColumns = ['id', 'title', 'status', 'created_at', 'author'];
    const sortCol = allowedColumns.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortOrder}`;

    // Limit results
    query += ` LIMIT 100`;

    const result = await pool.query(query, params);
    res.json({ data: result.rows });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/reports/bulk-update', extractTenant, async (req, res) => {
  try {
    const { report_ids, new_status, comment } = req.body;

    if (!Array.isArray(report_ids) || report_ids.length === 0) {
      return res.status(400).json({ error: 'report_ids must be non-empty array' });
    }

    if (report_ids.length > 50) {
      return res.status(400).json({ error: 'Maximum 50 reports per batch' });
    }

    // Build IN clause dynamically for the IDs
    const idPlaceholders = report_ids.map((_, i) => `$${i + 3}`).join(', ');

    const updateQuery = `UPDATE reports 
                         SET status = $1, 
                             updated_at = NOW(),
                             last_comment = $2
                         WHERE id IN (${idPlaceholders})
                         AND tenant_id = $${report_ids.length + 3}
                         RETURNING id, status`;

    const params = [new_status, comment, ...report_ids, req.tenantId];
    const result = await pool.query(updateQuery, params);

    res.json({ updated: result.rows });
  } catch (err) {
    console.error('Update error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Export endpoint - vulnerable to SQL injection via unparameterized input
app.get('/api/v2/reports/export', extractTenant, async (req, res) => {
  try {
    const { format, columns, filter_expr } = req.query;

    // Validate format
    const validFormats = ['csv', 'json'];
    if (!validFormats.includes(format)) {
      return res.status(400).json({ error: 'Invalid format' });
    }

    // Parse requested columns
    const requestedCols = columns ? columns.split(',') : ['id', 'title', 'status'];
    const safeCols = requestedCols.filter(c => 
      /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(c.trim())
    );

    if (safeCols.length === 0) {
      return res.status(400).json({ error: 'No valid columns specified' });
    }

    // Custom filter expression - DANGEROUS: directly interpolated
    // Developer note: "filter_expr is pre-validated by API gateway schema"
    let query = `SELECT ${safeCols.join(', ')} FROM reports WHERE tenant_id = '${req.tenantId}'`;

    if (filter_expr) {
      query += ` AND (${filter_expr})`;
    }

    query += ` LIMIT 10000`;

    const result = await pool.query(query);

    if (format === 'csv') {
      const header = safeCols.join(',');
      const rows = result.rows.map(r => safeCols.map(c => r[c]).join(','));
      res.setHeader('Content-Type', 'text/csv');
      res.send([header, ...rows].join('\n'));
    } else {
      res.json({ data: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

app.listen(3000, () => console.log('Report service listening on :3000'));
